/* Lazer DS Starter Kit tokens. Generated from the Figma variables (01 to 04). Do not edit by hand: retone 01 Primitives in Figma and regenerate. */
:root {
  /* 01 Primitives */
  --color-accent-100: #f2eee8;
  --color-accent-200: #e3dcce;
  --color-accent-300: #ccbda4;
