  --color-accent-700: #5f4f35;
  --color-accent-800: #483c28;
  --color-accent-900: #31291c;
  --color-alpha-black-10: #0000001a;
  --color-alpha-black-16: #00000029;
  --color-alpha-black-40: #00000066;
  --color-alpha-black-56: #0000008f;
  --color-alpha-black-6: #0000000f;
  --color-brand-100: #eaedf0;
  --color-brand-200: #d3d8df;
  --color-brand-300: #acb6c3;
  --color-brand-400: #8391a5;
  --color-brand-50: #f6f7f9;
  --color-brand-500: #5e6d82;
  --color-brand-600: #4d596a;
  --color-brand-700: #3e4856;
  --color-brand-800: #2f3741;
  --color-brand-900: #20252c;
  --color-chart-aqua-500: #1c9e72;
  --color-chart-blue-100: #dce8f7;
  --color-chart-blue-200: #b9d0ef;
  --color-chart-blue-300: #8fb4e4;
  --color-chart-blue-400: #6396d6;
  --color-chart-blue-500: #2f6fbf;
  --color-chart-blue-600: #24589a;
  --color-chart-blue-700: #1b4276;
  --color-chart-green-400: #3e9445;
  --color-chart-green-500: #2c7a32;
  --color-chart-magenta-400: #c67290;
  --color-chart-magenta-500: #d4789c;
  --color-chart-orange-500: #d2662f;
  --color-chart-red-100: #f5dedc;
  --color-chart-red-200: #e5b4b0;
  --color-chart-red-300: #d68983;
  --color-chart-red-400: #d05b55;
  --color-chart-red-500: #c4453f;
  --color-chart-red-600: #9e332e;
  --color-chart-red-700: #762321;
  --color-chart-violet-300: #7a6bd0;
  --color-chart-violet-500: #4a3f9e;
  --color-chart-yellow-500: #b58218;
  --color-neutral-0: #ffffff;
  --color-neutral-100: #f2f2f3;
  --color-neutral-1000: #000000;
  --color-neutral-200: #e2e3e4;
  --color-neutral-300: #c7c9cc;
  --color-neutral-400: #a4a8ad;
  --color-neutral-50: #fafafa;
  --color-neutral-500: #7e848b;
  --color-neutral-600: #666a70;
  --color-neutral-700: #505358;
  --color-neutral-800: #3a3d40;
  --color-neutral-900: #242628;
  --color-neutral-950: #131415;
  --color-utility-error-100: #f6e6e5;
  --color-utility-error-200: #ebcecc;
  --color-utility-error-500: #ae453d;
  --color-utility-error-700: #79302a;
  --color-utility-error-800: #441b18;
  --color-utility-info-100: #e6edf4;
  --color-utility-info-500: #4675a4;
  --color-utility-info-700: #315272;
  --color-utility-info-800: #1c2e40;
  --color-utility-success-100: #e4f2ea;
  --color-utility-success-500: #40825f;
  --color-utility-success-700: #2c5941;
  --color-utility-success-800: #1e3e2d;
  --color-utility-warning-100: #f5ede0;
  --color-utility-warning-500: #b28638;
  --color-utility-warning-700: #7c5d27;
  --color-utility-warning-800: #463416;
  --duration-0: 0ms;
  --duration-100: 100ms;
  --duration-1200: 1200ms;
  --duration-150: 150ms;
  --duration-200: 200ms;
  --duration-300: 300ms;
  --duration-400: 400ms;
  --duration-5000: 5000ms;
  --duration-600: 600ms;
  --duration-75: 75ms;
  --ease-accelerate: cubic-bezier(0.4, 0, 1, 1);
