  --radius-lg: 16px;
  --radius-md: 8px;
  --radius-none: 0px;
  --radius-sm: 4px;
  --space-0: 0px;
  --space-12: 12px;
  --space-16: 16px;
  --space-2: 2px;
  --space-20: 20px;
  --space-24: 24px;
  --space-32: 32px;
  --space-4: 4px;
  --space-40: 40px;
  --space-48: 48px;
  --space-56: 56px;
  --space-64: 64px;
  --space-8: 8px;
  --space-80: 80px;
  --space-96: 96px;
  --stroke-default: 1.5px;
  --stroke-fine: 1.33px;
  --stroke-hairline: 1px;
  --stroke-heavy: 2px;
  --stroke-medium: 1.67px;
  --stroke-thick: 3px;
  --type-family-display: "Inter", system-ui, sans-serif;
  --type-family-mono: "IBM Plex Mono", ui-monospace, monospace;
  --type-family-text: "Inter", system-ui, sans-serif;
  --type-leading-normal: 1.5;
  --type-leading-relaxed: 1.65;
  --type-leading-snug: 1.25;
  --type-leading-tight: 1.1;
  --type-size-10: 10px;
  --type-size-11: 11px;
  --type-size-12: 12px;
  --type-size-120: 120px;
  --type-size-13: 13px;
  --type-size-14: 14px;
  --type-size-16: 16px;
  --type-size-18: 18px;
  --type-size-20: 20px;
  --type-size-24: 24px;
  --type-size-30: 30px;
  --type-size-36: 36px;
  --type-size-48: 48px;
  --type-size-60: 60px;
  --type-size-72: 72px;
  --type-size-96: 96px;
  --type-style-bold: Bold;
  --type-style-medium: Medium;
  --type-style-regular: Regular;
  --type-style-semibold: Semi Bold;
  --type-weight-regular: 400; /* derived from type/style/regular */
  --type-weight-medium: 500; /* derived from type/style/medium */
  --type-weight-semibold: 600; /* derived from type/style/semibold */
  --type-weight-bold: 700; /* derived from type/style/bold */
  /* 02 Semantic, Light */
