  --text-muted: var(--color-neutral-600);
  --text-inverse: var(--color-neutral-0);
  --text-link: var(--color-brand-600);
  --text-disabled: var(--color-neutral-500);
  --text-on-action: var(--color-neutral-0);
  --surface-page: var(--color-neutral-0);
  --surface-raised: var(--color-neutral-0);
  --surface-sunken: var(--color-neutral-50);
  --surface-inverse: var(--color-neutral-900);
  --surface-overlay: var(--color-neutral-800);
  --border-subtle: var(--color-neutral-100);
  --border-default: var(--color-neutral-200);
  --border-strong: var(--color-neutral-500);
  --border-focus: var(--color-brand-500);
  --action-primary: var(--color-brand-600);
  --action-primary-hover: var(--color-brand-700);
  --action-secondary: var(--color-accent-700);
  --action-secondary-hover: var(--color-accent-800);
  --action-destructive: var(--color-utility-error-700);
  --action-disabled: var(--color-neutral-100);
  --feedback-success: var(--color-utility-success-700);
  --feedback-warning: var(--color-utility-warning-700);
  --feedback-error: var(--color-utility-error-700);
  --feedback-info: var(--color-utility-info-700);
  --surface-muted: var(--color-neutral-100);
  --action-destructive-hover: var(--color-utility-error-500);
  --feedback-success-subtle: var(--color-utility-success-100);
  --feedback-warning-subtle: var(--color-utility-warning-100);
  --feedback-error-subtle: var(--color-utility-error-100);
  --feedback-info-subtle: var(--color-utility-info-100);
  --feedback-info-on-inverse: var(--color-utility-info-100);
  --feedback-success-on-inverse: var(--color-utility-success-100);
  --feedback-error-on-inverse: var(--color-utility-error-100);
  --surface-selected: var(--color-brand-100);
  --feedback-success-border: var(--color-utility-success-500);
  --feedback-warning-border: var(--color-utility-warning-500);
  --feedback-error-border: var(--color-utility-error-500);
  --feedback-info-border: var(--color-utility-info-500);
  --chart-series-1: var(--color-chart-blue-500);
  --chart-series-2: var(--color-chart-orange-500);
  --chart-series-3: var(--color-chart-aqua-500);
  --chart-series-4: var(--color-chart-yellow-500);
  --chart-series-5: var(--color-chart-magenta-500);
  --chart-series-6: var(--color-chart-green-500);
  --chart-series-7: var(--color-chart-violet-500);
  --chart-series-8: var(--color-chart-red-500);
  --chart-sequential-1: var(--color-chart-blue-100);
  --chart-sequential-2: var(--color-chart-blue-200);
  --chart-sequential-3: var(--color-chart-blue-300);
  --chart-sequential-4: var(--color-chart-blue-400);
  --chart-sequential-5: var(--color-chart-blue-500);
  --chart-sequential-6: var(--color-chart-blue-600);
  --chart-sequential-7: var(--color-chart-blue-700);
  --chart-diverging-neg-3: var(--color-chart-red-600);
  --chart-diverging-neg-2: var(--color-chart-red-500);
  --chart-diverging-neg-1: var(--color-chart-red-300);
  --chart-diverging-mid: var(--color-neutral-100);
  --chart-diverging-pos-1: var(--color-chart-blue-300);
  --chart-diverging-pos-2: var(--color-chart-blue-500);
  --chart-diverging-pos-3: var(--color-chart-blue-600);
  --chart-surface: var(--color-neutral-0);
  --chart-grid: var(--color-neutral-100);
  --chart-axis: var(--color-neutral-300);
  --chart-label: var(--color-neutral-600);
  --elevation-shadow-raised: var(--color-alpha-black-6);
  --elevation-shadow-overlay: var(--color-alpha-black-10);
  --elevation-shadow-modal: var(--color-alpha-black-16);
  --surface-scrim: var(--color-neutral-1000);
  --border-strongest: var(--color-neutral-600);
  --surface-inverse-raised: var(--color-neutral-800);
