  --inset-sm: var(--space-8);
  --inset-md: var(--space-12);
  --inset-lg: var(--space-16);
  --inset-xl: var(--space-20);
  --inset-2xl: var(--space-24);
  --inset-3xl: var(--space-32);
  --inset-4xl: var(--space-48);
  --stack-2xs: var(--space-2);
  --stack-xs: var(--space-4);
  --stack-sm: var(--space-8);
  --stack-md: var(--space-12);
  --stack-lg: var(--space-16);
  --stack-xl: var(--space-20);
  --stack-2xl: var(--space-24);
  --stack-3xl: var(--space-32);
  --stack-4xl: var(--space-48);
  --inline-2xs: var(--space-2);
  --inline-xs: var(--space-4);
  --inline-sm: var(--space-8);
  --inline-md: var(--space-12);
  --inline-lg: var(--space-16);
  --inline-xl: var(--space-20);
  --inline-2xl: var(--space-24);
  --inline-3xl: var(--space-32);
  --inline-4xl: var(--space-48);
