  --motion-duration-fast: var(--duration-150);
  --motion-duration-base: var(--duration-200);
  --motion-duration-slow: var(--duration-300);
  --motion-duration-dwell: var(--duration-5000);
  --motion-duration-loop: var(--duration-1200);
