  --motion-ease-entrance: var(--ease-decelerate);
  --motion-ease-exit: var(--ease-accelerate);
  --motion-ease-loop: var(--ease-linear);
  --motion-ease-spring: var(--ease-overshoot);
  --motion-duration-intent: var(--duration-300);
  --motion-stagger-base: var(--duration-75);
  --motion-stagger-loose: var(--duration-150);
  --motion-duration-hold: var(--duration-600);
  /* 04 Responsive, Desktop */
