/* Text styles, one class per Figma text style (Heading/H1 is .lz-h1, Label/Caps is .lz-label-caps) */
.lz-h1 { font-family: var(--type-family-display); font-weight: var(--type-weight-bold); font-size: var(--scale-h1); line-height: 1.1; letter-spacing: -0.02em; }
.lz-h2 { font-family: var(--type-family-display); font-weight: var(--type-weight-bold); font-size: var(--scale-h2); line-height: 1.1; letter-spacing: -0.02em; }
